'use client';

/**
 * <RoxyVedicKundli data={...} />: South, North, or East Indian Vedic kundli for /vedic-astrology/birth-chart with per-planet degree and nakshatra detail, plus an optional Chandra Lagna (Moon-as-ascendant) reference view.
 *
 * You own this file. Customize freely. The component is re-exported from
 * @roxyapi/ui-react and stays in sync with the published package.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/vedic-kundli/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   const { data } = await roxy.vedicAstrology.generateBirthChart({ body: await req.json() });
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyVedicKundli as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyVedicKundliProps = ComponentProps<typeof Element>;

export function RoxyVedicKundli(props: RoxyVedicKundliProps) {
	return <Element {...props} />;
}

export default RoxyVedicKundli;
